"""
Algorithm 1 -- The Exact Linear Move Classifier and Linear-Time Seed Recovery
over the Integers.

Given a single positive Pythagorean triple lying in the Barning--Hall tree
rooted at (3,4,5), reconstruct the entire control word in O(k) arithmetic
operations, using two integer comparisons and one 3x3 matrix-vector product
per recovered letter.
"""

from __future__ import annotations

from typing import List, Tuple

Triple = Tuple[int, int, int]
Word = Tuple[int, ...]

ROOT: Triple = (3, 4, 5)


def apply_move(i: int, v: Triple) -> Triple:
    """Apply the Berggren move B_i, i in {1,2,3}, to v = (a,b,c)."""
    a, b, c = v
    if i == 1:
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    if i == 3:
        return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)
    raise ValueError("move index must be 1, 2 or 3")


def inv_move(i: int, v: Triple) -> Triple:
    """Apply B_i^{-1} = Q B_i^T Q with Q = diag(1,1,-1)."""
    a, b, c = v
    if i == 1:
        return (a + 2 * b - 2 * c, -2 * a - b + 2 * c, -2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)
    if i == 3:
        return (-a - 2 * b + 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)
    raise ValueError("move index must be 1, 2 or 3")


def which_move(v: Triple) -> int:
    """The exact classifier.

    Returns the unique move that produced v, reading only the first and third
    coordinates:  B_1 iff 5a < 3c;  B_2 iff 3c <= 5a < 4c;  B_3 otherwise.

    The thresholds are the images of the Euclid-parameter ratio tests
    m < 2n, 2n < m < 3n, m > 3n under m/n = sqrt((c+a)/(c-a)).
    """
    a, _b, c = v
    if 5 * a < 3 * c:
        return 1
    if 5 * a < 4 * c:
        return 2
    return 3


def apply_word(word: List[int] | Word, v: Triple = ROOT) -> Triple:
    """Run a control word from left to right."""
    for i in word:
        v = apply_move(i, v)
    return v


def recover_seed(v: Triple, root: Triple = ROOT, max_steps: int = 100_000) -> Word:
    """Recover the control word from a single observed state.

    Correctness rests on two facts: the classifier is exact on every child of a
    positive Pythagorean triple, and every move strictly increases the
    hypotenuse, so the peeling loop terminates exactly at the root.

    Complexity: O(k) arithmetic operations for a word of length k, i.e. two
    comparisons and nine multiply-adds per letter.
    """
    peeled: List[int] = []
    steps = 0
    while v != root:
        if steps >= max_steps:
            raise RuntimeError("input does not lie in the tree above the root")
        i = which_move(v)
        peeled.append(i)
        v = inv_move(i, v)
        steps += 1
    return tuple(reversed(peeled))


if __name__ == "__main__":
    from itertools import product

    print("Exhaustive verification of exact recovery, words of length 1..9\n")
    for k in range(1, 10):
        ok = all(recover_seed(apply_word(list(w))) == w
                 for w in product((1, 2, 3), repeat=k))
        print(f"  k = {k}:  all {3 ** k:>6} words recovered exactly: {ok}")

    print("\nA worked example:")
    secret: Word = (2, 3, 1, 1, 2, 3, 3, 1, 2, 2, 1)
    state = apply_word(list(secret))
    print(f"  secret word    : {secret}")
    print(f"  observed state : {state}")
    print(f"  Pythagorean    : {state[0]**2 + state[1]**2 == state[2]**2}")
    print(f"  recovered word : {recover_seed(state)}")
    print(f"  match          : {recover_seed(state) == secret}")

"""
Algorithm 2 -- Modular Seed Recovery by Canonical Lifting, with Certified
Wrap-Around Detection.

An observer who sees only the residues (a,b,c) mod m lifts each to its
representative in [0,m) and runs the integer classifier.  This is provably
correct as long as no state along the trajectory has hypotenuse >= m, which is
guaranteed by the growth bound c <= 5*7^k.  The routine below runs the decoder
and simultaneously certifies whether the caller is inside the safe regime.
"""

from __future__ import annotations

from typing import List, Optional, Tuple

Triple = Tuple[int, int, int]
Word = Tuple[int, ...]

ROOT: Triple = (3, 4, 5)


def apply_move(i: int, v: Triple) -> Triple:
    a, b, c = v
    if i == 1:
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def inv_move(i: int, v: Triple) -> Triple:
    a, b, c = v
    if i == 1:
        return (a + 2 * b - 2 * c, -2 * a - b + 2 * c, -2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)
    return (-a - 2 * b + 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


def red(v: Triple, m: int) -> Triple:
    """Coordinatewise reduction with representatives in [0, m): the lift."""
    return (v[0] % m, v[1] % m, v[2] % m)


def which_move(v: Triple) -> int:
    a, _b, c = v
    if 5 * a < 3 * c:
        return 1
    if 5 * a < 4 * c:
        return 2
    return 3


def state_mod(word: List[int] | Word, m: int) -> Triple:
    """The observation.  Computed inside (Z/m)^3, valid by equivariance."""
    w = red(ROOT, m)
    for i in word:
        w = red(apply_move(i, w), m)
    return w


def safe_length(m: int) -> int:
    """The largest k with 5 * 7^k < m: the certified wrap-free word length."""
    k, bound = 0, 5
    while bound * 7 < m:
        bound *= 7
        k += 1
    return k if bound < m else max(k - 1, 0)


def recover_seed_mod(observation: Triple, m: int,
                     max_steps: int = 100_000) -> Optional[Word]:
    """Self-terminating modular peeling.

    Returns the control word, or None if the loop fails to reach the root
    within `max_steps` (which happens exactly when the state has wrapped and
    the classifier has been misled).

    Certified correct for every word of length <= safe_length(m).
    Provably incorrect for some word of length k whenever m^3 < 3^k.

    Complexity: O(k) modular operations, each on numbers of size O(log m).
    """
    target = red(ROOT, m)
    w = red(observation, m)
    peeled: List[int] = []
    steps = 0
    while w != target:
        if steps >= max_steps:
            return None
        i = which_move(w)
        peeled.append(i)
        w = red(inv_move(i, w), m)
        steps += 1
    return tuple(reversed(peeled))


if __name__ == "__main__":
    from itertools import product

    print("Certified safe word lengths:\n")
    print(f"{'m':>14}{'safe_length(m)':>18}{'5*7^k bound':>18}")
    print("-" * 50)
    for m in (36, 246, 1716, 12006, 10 ** 6, 10 ** 12, 2 ** 64):
        k = safe_length(m)
        print(f"{m:>14}{k:>18}{5 * 7 ** k:>18}")

    print("\nInside the safe regime recovery is exact:")
    for k in range(1, 5):
        m = 5 * 7 ** k + 1
        ok = all(recover_seed_mod(state_mod(list(w), m), m) == w
                 for w in product((1, 2, 3), repeat=k))
        print(f"  k = {k}, m = {m:>7}: all {3 ** k:>4} words recovered: {ok}")

    print("\nOutside it, recovery breaks -- and the counting bound says it must:")
    for m, k in ((7, 3), (11, 5), (13, 6)):
        wrong = 0
        wrongest = None
        for w in product((1, 2, 3), repeat=k):
            got = recover_seed_mod(state_mod(list(w), m), m, max_steps=200)
            if got != w:
                wrong += 1
                if wrongest is None:
                    wrongest = (w, got)
        print(f"  m = {m:>3}, k = {k}:  m^3 = {m**3:>6} vs 3^k = {3**k:>6}"
              f"   -> {wrong}/{3**k} words mis-decoded")
        if wrongest is not None:
            print(f"      e.g. true {wrongest[0]}  ->  decoded {wrongest[1]}")
